//--------------------------------------------------------------------------//
//
// Name  : crc_calc_crc_16
//
// Desc  : This function updates the 16-bit CRC with the current DATA byte.
//
//         
//
//         To test algorithm:
//
//
// Args  : crc  = The CRC to update.
//
//         data = The data byte to add to CRC.
//         
//         poly = 3 poly (see note)
//
// Retv  : void
//
// Assum :
//
// Notes :
//
//         Name   : "CRC-16/CITT"
//         Width  : 16
//         Poly   : 1021
//         Init   : FFFF
//         RefIn  : False
//         RefOut : False
//         XorOut : 0000
//         Check  : ?
//        
//        
//         Name   : "XMODEM"
//         Width  : 16
//         Poly   : 8408
//         Init   : 0000
//         RefIn  : True
//         RefOut : True
//         XorOut : 0000
//         Check  : ?
//        
//        
//         Name   : "ARC"
//         Width  : 16
//         Poly   : 8005
//         Init   : 0000
//         RefIn  : True
//         RefOut : True
//         XorOut : 0000
//         Check  : ?
// 
//--------------------------------------------------------------------------//

void crc_calc_crc_16 (UInt16 * crc , UInt8 data, Crc_Poly_16 poly)
{
  UInt8    bit  ;
  unsigned n    ;

  for (n = 8 ; n > 0 ; n--)
    {
      bit = (*crc ^ data) & 0x01 ;

      *crc >>= 1 ;

      if (bit) *crc ^= poly ;

      data >>= 1 ;
    }
}

